package com.autocare.service;
import com.autocare.dto.request.*;import com.autocare.dto.response.*;import com.autocare.entity.*;import com.autocare.enums.*;import com.autocare.exception.*;import com.autocare.repository.*;import com.autocare.security.*;import jakarta.transaction.Transactional;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import java.util.*;
@Service @Transactional public class ServiceCaseWorkflowService {private final ServiceCaseRepository cases;private final EmployeeRepository employees;private final DiagnosisRepository diagnoses;private final ServiceItemRepository items;private final CurrentUserService current;public ServiceCaseWorkflowService(ServiceCaseRepository c,EmployeeRepository e,DiagnosisRepository d,ServiceItemRepository i,CurrentUserService x){cases=c;employees=e;diagnoses=d;items=i;current=x;}public List<ServiceCaseDetailResponse> list(){CurrentUser u=current.requireCurrentUser();List<ServiceCase> all=cases.findAll();if(workshop(u))return all.stream().map(this::dto).toList();Customer c=current.requireCurrentCustomer();return all.stream().filter(x->x.getCustomer().getId().equals(c.getId())).map(this::dto).toList();}public ServiceCaseDetailResponse get(String id){ServiceCase c=find(id);access(c);return dto(c);}public ServiceCaseDetailResponse priority(String id,PriorityRequest r){ServiceCase c=work(id);c.setPriority(r.priority());return dto(c);}public ServiceCaseDetailResponse assign(String id,AssignmentRequest r){ServiceCase c=work(id);Employee e=employees.findByEmployeeId(r.employeeId()).orElseThrow(()->new ResourceNotFoundException("Employee not found"));if(!e.isActive())throw new IllegalStateException("Employee is inactive");c.setAssignedEmployee(e);return dto(c);}public ServiceCaseDetailResponse startDiagnosis(String id){return move(id,ServiceCaseStatus.CHECKED_IN,ServiceCaseStatus.DIAGNOSIS);}public ServiceCaseDetailResponse saveDiagnosis(String id,TextRequest r){ServiceCase c=work(id);if(c.getStatus()!=ServiceCaseStatus.DIAGNOSIS)throw new IllegalStateException("Diagnosis can only be recorded during diagnosis");Diagnosis d=diagnoses.findFirstByServiceCase_ServiceCaseIdOrderByDiagnosedAtDesc(id).orElseGet(()->new Diagnosis(c,r.value().trim(),null));d.update(r.value().trim(),d.getTechnicianNotes());diagnoses.save(d);c.setDiagnosis(r.value().trim());return dto(c);}public ServiceCaseDetailResponse submitDiagnosis(String id){ServiceCase c=work(id);if(c.getStatus()!=ServiceCaseStatus.DIAGNOSIS||c.getDiagnosis()==null||c.getDiagnosis().isBlank())throw new IllegalStateException("A diagnosis is required");c.setStatus(ServiceCaseStatus.WAITING_FOR_APPROVAL);return dto(c);}public ServiceCaseDetailResponse approve(String id){return move(id,ServiceCaseStatus.WAITING_FOR_APPROVAL,ServiceCaseStatus.IN_SERVICE);}public ServiceCaseDetailResponse solution(String id,TextRequest r){ServiceCase c=work(id);c.setSolution(r.value().trim());return dto(c);}public ServiceCaseDetailResponse notes(String id,TextRequest r){ServiceCase c=work(id);c.setTechnicianNotes(r.value().trim());return dto(c);}public List<ServiceItemResponse> items(String id){access(find(id));return items.findByServiceCase_ServiceCaseId(id).stream().map(x->new ServiceItemResponse(x.getId(),x.getName(),x.getDescription(),x.getQuantity())).toList();}public ServiceItemResponse addItem(String id,ServiceItemRequest r){ServiceCase c=work(id);if(c.getStatus()!=ServiceCaseStatus.IN_SERVICE)throw new IllegalStateException("Items can only be added while in service");ServiceItem i=items.save(new ServiceItem(c,r.name().trim(),r.description(),r.quantity()));return new ServiceItemResponse(i.getId(),i.getName(),i.getDescription(),i.getQuantity());}public void deleteItem(String id,Long itemId){work(id);ServiceItem i=items.findById(itemId).orElseThrow(()->new ResourceNotFoundException("Service item not found"));if(!items.findByServiceCase_ServiceCaseId(id).contains(i))throw new IllegalStateException("Service item belongs to another case");items.delete(i);}public ServiceCaseDetailResponse payment(String id){return move(id,ServiceCaseStatus.IN_SERVICE,ServiceCaseStatus.PAYMENT_PENDING);}public ServiceCaseDetailResponse ready(String id){ServiceCase c=work(id);if(c.getStatus()!=ServiceCaseStatus.PAYMENT_PENDING||c.getDiagnosis()==null||c.getSolution()==null)throw new IllegalStateException("Diagnosis and solution are required before pickup");c.ready();return dto(c);}public ServiceCaseDetailResponse hold(String id){ServiceCase c=work(id);if(!Set.of(ServiceCaseStatus.DIAGNOSIS,ServiceCaseStatus.WAITING_FOR_APPROVAL,ServiceCaseStatus.IN_SERVICE).contains(c.getStatus()))throw new IllegalStateException("Case cannot be put on hold");c.setStatus(ServiceCaseStatus.ON_HOLD);return dto(c);}public ServiceCaseDetailResponse cancel(String id){ServiceCase c=work(id);if(Set.of(ServiceCaseStatus.READY_FOR_PICKUP,ServiceCaseStatus.CANCELLED).contains(c.getStatus()))throw new IllegalStateException("Case cannot be cancelled");c.setStatus(ServiceCaseStatus.CANCELLED);return dto(c);}private ServiceCaseDetailResponse move(String id,ServiceCaseStatus from,ServiceCaseStatus to){ServiceCase c=work(id);if(c.getStatus()!=from)throw new IllegalStateException("Invalid service case transition");c.setStatus(to);return dto(c);}private ServiceCase find(String id){return cases.findByServiceCaseId(id).orElseThrow(()->new ResourceNotFoundException("Service case not found"));}private ServiceCase work(String id){CurrentUser u=current.requireCurrentUser();if(!workshop(u))throw new AccessDeniedException("Workshop access is required");return find(id);}private void access(ServiceCase c){CurrentUser u=current.requireCurrentUser();if(workshop(u))return;Customer x=current.requireCurrentCustomer();if(!c.getCustomer().getId().equals(x.getId()))throw new AccessDeniedException("You cannot access this service case");}private boolean workshop(CurrentUser u){return Set.of("EMPLOYEE","MANAGER","OWNER").contains(u.role());}private ServiceCaseDetailResponse dto(ServiceCase c){Employee e=c.getAssignedEmployee();Vehicle v=c.getVehicle();return new ServiceCaseDetailResponse(c.getServiceCaseId(),c.getCustomer().getCustomerId(),c.getCustomer().getName(),v.getVehicleId(),v.getMake()+" "+v.getModel(),v.getLicensePlate(),c.getVisitType(),c.getServiceType(),c.getPriority(),c.getStatus(),e==null?null:e.getEmployeeId(),e==null?null:e.getName(),c.getDiagnosis(),c.getSolution(),c.getTechnicianNotes(),c.getCheckInTime(),c.getReadyForPickupAt());}}
